import time
from typing import Dict, List, Tuple, Union

class SlidingWindowLogLimiter:
    """A sliding‑window rate limiter that tracks request timestamps per key.

    The implementation stores a list of timestamps for each *key* and, on each
    request, discards entries that fall outside the configured ``window_seconds``.
    If the number of remaining timestamps is below ``max_requests`` the request
    is allowed; otherwise it is rejected.

    Defensive programming measures:
    * Strict type validation – booleans are explicitly rejected where numeric
      values are expected.
    * Parameter validation for ``max_requests`` (positive int) and
      ``window_seconds`` (positive number).
    * Validation of ``key`` (non‑empty string) and ``now`` (numeric timestamp).
    * All state mutations are performed atomically – the original bucket state
      is restored if an unexpected exception occurs.
    """

    def __init__(self, max_requests: int = 5, window_seconds: Union[int, float] = 60.0):
        # ----- Parameter validation -----
        if type(max_requests) is not int:
            raise ValueError("max_requests must be an int (bool is not allowed)")
        if max_requests <= 0:
            raise ValueError("max_requests must be a positive integer")
        if isinstance(window_seconds, bool) or not isinstance(window_seconds, (int, float)):
            raise ValueError("window_seconds must be a numeric type (bool is not allowed)")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")

        self.max_requests: int = max_requests
        self.window_seconds: float = float(window_seconds)
        # Mapping: key -> list of timestamps (float)
        self.buckets: Dict[str, List[float]] = {}

    def _validate_key(self, key: str) -> None:
        if isinstance(key, bool) or not isinstance(key, str):
            raise ValueError("key must be a non‑boolean string")
        if not key:
            raise ValueError("key must be a non‑empty string")

    def _validate_now(self, now: Union[int, float]) -> float:
        if isinstance(now, bool) or not isinstance(now, (int, float)):
            raise ValueError("now must be a numeric timestamp (bool is not allowed)")
        return float(now)

    def allow(self, key: str, now: Union[int, float, None] = None) -> Tuple[bool, int]:
        """Determine whether a request identified by *key* is allowed.

        Returns a tuple ``(allowed, current_count)`` where ``current_count`` is the
        number of requests counted within the sliding window *after* the decision
        (i.e., ``max_requests`` when the request is rejected).
        """
        # ----- Input validation -----
        self._validate_key(key)
        now_ts = self._validate_now(time.time() if now is None else now)

        # ----- Atomic state mutation -----
        # Keep a shallow copy of the bucket list for rollback on unexpected errors.
        original_bucket = None
        try:
            # Retrieve or create the timestamp list for the key.
            timestamps = self.buckets.get(key)
            if timestamps is None:
                timestamps = []
                self.buckets[key] = timestamps
            else:
                # Store original for potential rollback.
                original_bucket = timestamps.copy()

            # Prune timestamps outside the sliding window.
            cutoff = now_ts - self.window_seconds
            # Since the list is maintained in chronological order, we can remove
            # from the front efficiently.
            while timestamps and timestamps[0] <= cutoff:
                timestamps.pop(0)

            if len(timestamps) < self.max_requests:
                timestamps.append(now_ts)
                return True, len(timestamps)
            else:
                return False, len(timestamps)
