            # Rollback to the original state if something went wrong after we
            # mutated the bucket.
            if original_bucket is not None:
                self.buckets[key] = original_bucket
            elif key in self.buckets and original_bucket is None:
                # The bucket was newly created but an error occurred before any
                # timestamps were added – remove the empty bucket.
                self.buckets.pop(key, None)
            raise

